260	## 3. Section JSON Schema
261	
262	Each template version stores `sections: ConsentSection[]` in JSONB. Full typed schema:
263	
264	```typescript
265	// types/consent.ts
266	
267	type SectionKind =
268	  | 'heading'
269	  | 'paragraph'
270	  | 'signature'
271	  | 'checkbox'
272	  | 'text_input'
273	  | 'date'
274	  | 'dropdown'
275	  | 'file_upload'
276	  | 'initials'
277	  | 'ink_disclosure'
278	  | 'reach_batch_record';
279	
280	interface BaseSection {
281	  id: string;          // nanoid(10) — stable across edits
282	  kind: SectionKind;
283	  label: string;       // shown above section to signer
284	  required: boolean;
285	  order: number;       // integer, 0-indexed, contiguous
286	}
287	
288	interface HeadingSection extends BaseSection {
289	  kind: 'heading';
290	  level: 1 | 2 | 3;   // maps to text-2xl / text-xl / text-lg
291	}
292	
293	interface ParagraphSection extends BaseSection {
294	  kind: 'paragraph';
295	  body: string;        // markdown, rendered via react-markdown
296	}
297	
298	interface SignatureSection extends BaseSection {
299	  kind: 'signature';
300	  signer: 'client' | 'guardian';  // guardian = second pad
301	}
302	
303	interface CheckboxSection extends BaseSection {
304	  kind: 'checkbox';
305	  body: string;        // markdown text of the checkbox statement
306	}
307	
308	interface TextInputSection extends BaseSection {
309	  kind: 'text_input';
310	  placeholder?: string;
311	  min_length?: number;
312	  max_length?: number;
313	  regex?: string;      // stored as string, validated on submit
314	  regex_error?: string;
315	}
316	
317	interface DateSection extends BaseSection {
318	  kind: 'date';
319	  min_age?: number;    // e.g. 18 — shows warning if DOB is under this age
320	}
321	
322	interface DropdownSection extends BaseSection {
323	  kind: 'dropdown';
324	  options: { value: string; label: string }[];
325	}
326	
327	interface FileUploadSection extends BaseSection {
